"""RoboPaint 春: camera-calibrated brush trajectories. No simulator internals.
Run commands from JSON; all executed commands and camera observations are retained.
"""
import sys,os,json,time
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot
r=Robot()
OUT='/app/output'
Q=[0.,1.,0.,0.]
ZP=.0202
S=.227185/1024

def pose(u,v,z,practice=False):
    return [-.1+(512-v-.5)*S, ((224-u-.5)*S-.1856) if practice else (512-u-.5)*S,z]+Q

def submit(rows,note='',dt=.05,cameras=['practice_cam']):
    for i in range(0,len(rows),180):
        a=rows[i:i+180]
        before=r.status()
        try:res=r.submit('ee_pose',a,dt=dt,cameras=cameras,video='none',note=note)
        except Exception:
            r.wait_ready();after=r.status()
            if after['control_steps']!=before['control_steps']:raise RuntimeError('Uncertain completed call; inspect status before proceeding')
            res=r.submit('ee_pose',a,dt=dt,cameras=cameras,video='none',note=note)
        n=res.meta['calls'];res.save(f'/app/runs/{n:04d}')
        for c,im in res.last.items():Image.fromarray(im).save(f'{OUT}/last_{c}.png')
        json.dump(res.meta,open(f'{OUT}/last_meta.json','w'),indent=2)
        print('CALL',n,'steps',res.meta['control_steps'],'tip',res.meta['proprio']['now'][7:10],'plan',res.meta.get('plan'),flush=True)
        if res.stopped:raise RuntimeError('Partial call')

def move(p,duration=1.,note='travel'):
    start=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:14]); p=np.array(p)
    n=max(int(duration/.05),int(np.linalg.norm(p[:3]-start[:3])/.004)+1)
    submit([start+(p-start)*t for t in np.linspace(0,1,n+1)[1:]],note)

def observe():
    o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save('/app/runs/observe'+str(o.meta['calls']))
    for c,im in o.last.items():Image.fromarray(im).save(f'{OUT}/last_{c}.png')
    print('OBS',o.meta['calls'],o.meta['time_left_s'],flush=True)

def run(cmd):
    if cmd['op']=='move':move(cmd['pose'],cmd.get('duration',1),cmd.get('note','travel'))
    elif cmd['op']=='rows':submit(cmd['rows'],cmd.get('note','stroke'),cmd.get('dt',.05),cmd.get('cameras',['practice_cam']))
    elif cmd['op']=='observe':observe()
    elif cmd['op']=='status':print(r.status(),flush=True)

if __name__=='__main__':
    if len(sys.argv)>1:
        cmds=json.load(open(sys.argv[1]));cmds=cmds if isinstance(cmds,list) else [cmds]
        for cmd in cmds:run(cmd)
    else:
        print('READY',flush=True)
        for line in sys.stdin:
            try:run(json.loads(line))
            except Exception as e:print('ERROR',repr(e),flush=True)
